// 加载模型
load: func(
    builder: list<graph-builder-array>,
    encoding: graph-encoding,
    target: execution-target
) -> result<graph, error>

// 初始化执行上下文
init-execution-context: func(graph: graph) -> result<graph-execution-context, error>

// 设置输入
set-input: func(
    ctx: graph-execution-context,
    index: u32,
    tensor: tensor
) -> result<_, error>

// 执行推理
